<?php
// Only the guarded, disposable integration database. Never production accounts.
$abilityPassword='Ability-fixture-password-2026!';
$pdo->prepare('INSERT INTO quiz_users(username,email,password_hash,avatar_key,email_verified_at) VALUES(?,?,?,?,NOW())')->execute(['ability'.$suffix,'ability'.$suffix.'@example.test',password_hash($abilityPassword,PASSWORD_DEFAULT),'hero']);
$abilityUser=(int)$pdo->lastInsertId();request('account-login',['identifier'=>'ability'.$suffix,'password'=>$abilityPassword]);
$abilityCat=request('admin-category-save',['title'=>'Ability category '.$suffix,'enabled'=>true,'worldIds'=>['italien']])['id'];
$abilityQuestionIds=[];
for($n=0;$n<7;$n++)$abilityQuestionIds[]=request('admin-question-save',['categoryId'=>$abilityCat,'question'=>'Ability question '.$n.' '.$suffix,'answers'=>['A','B','C','D'],'correct'=>0,'difficulty'=>'medium','active'=>true,'worldIds'=>[]])['id'];
$roundPayload=['categoryId'=>$abilityCat,'questionIds'=>array_slice($abilityQuestionIds,0,5)];
$roundAnswers=static fn($questions)=>array_map(static fn($q)=>['questionId'=>$q['id'],'selectedAnswers'=>[0]],$questions);
$inventory=request('account-abilities',[]);
check(count($inventory['items'])===1&&!$inventory['items'][0]['unlocked']&&$inventory['items'][0]['current']===0,'new accounts have a locked assigned ability and zero invented historic progress');
request('account-ability-equip',['heroKey'=>'hero','abilityId'=>'heldenblick'],404);
request('account-abilities',[],403,'',false);
for($n=0;$n<3;$n++){
    $r=request('start-round',$roundPayload);check($r['abilities']===[],'unlearned abilities are not available');
    $submission=['roundId'=>$r['roundId'],'answers'=>$roundAnswers($r['questions'])];$award=request('save-result',$submission);
    $again=request('save-result',$submission);check($again['abilityAwards']===$award['abilityAwards'],'result retry returns same ability awards without duplicate learning progress');
}
$inventory=request('account-abilities',[]);check($inventory['items'][0]['unlocked']&&$inventory['items'][0]['current']===3&&count($award['abilityAwards'])===1,'three qualifying rounds unlock the ability exactly once');
$r=request('start-round',$roundPayload);check(array_column($r['abilities'],'id')===['heldenblick'],'learned ability is automatically frozen into the round');
$action=['roundId'=>$r['roundId'],'actionId'=>str_repeat('a',32),'abilityId'=>'heldenblick','position'=>0,'answers'=>[['questionId'=>$r['questions'][0]['id'],'selectedAnswers'=>[]]]];
request('use-round-ability',$action,422);
$action['answers'][0]['selectedAnswers']=[1];$used=request('use-round-ability',$action);
check(in_array($used['removedAnswer'],[2,3],true),'Heldenblick removes a server-selected false answer after the first mistake');
check(request('use-round-ability',$action)==$used,'ability request replay is idempotent');
request('use-round-ability',array_replace($action,['actionId'=>str_repeat('b',32)]),409);
$answers=$roundAnswers($r['questions']);request('save-result',['roundId'=>$r['roundId'],'answers'=>$answers],422);
$answers[0]['selectedAnswers']=[1,$used['removedAnswer']];request('save-result',['roundId'=>$r['roundId'],'answers'=>$answers],422);
$answers[0]['selectedAnswers']=[1,0];$saved=request('save-result',['roundId'=>$r['roundId'],'answers'=>$answers]);
check((int)$pdo->query('SELECT score FROM quiz_results WHERE id='.(int)$saved['resultId'])->fetchColumn()===13,'assisted elimination keeps ordinary second-try scoring and validates the frozen answer prefix');
request('use-round-ability',$action,409);
$adminAbilityData=request('admin-abilities');$heroRow=array_column($adminAbilityData['heroes'],null,'avatar_key')['hero'];
$assign=['heroKey'=>'hero','contentVersion'=>$heroRow['contentVersion'],'abilityIds'=>['heldenblick','schutzschild','neues-abenteuer']];
request('admin-hero-abilities-save',$assign,403,'',false);request('admin-hero-abilities-save',$assign);request('admin-hero-abilities-save',$assign,409);
check(true,'hero assignments require CSRF and reject stale edits');
// Test-only entitlement fixtures let each implemented effect be exercised directly.
foreach(['schutzschild','neues-abenteuer'] as $aid)$pdo->prepare('INSERT INTO quiz_user_abilities(user_id,ability_id,hero_key) VALUES(?,?,?)')->execute([$abilityUser,$aid,'hero']);
$multi=request('start-round',$roundPayload);
check(count($multi['abilities'])===3,'three learned abilities are available together without profile equipment');
$multiAction=['roundId'=>$multi['roundId'],'actionId'=>str_repeat('1',32),'abilityId'=>'neues-abenteuer','position'=>0,'answers'=>[['questionId'=>$multi['questions'][0]['id'],'selectedAnswers'=>[]]]];
$multiSwap=request('use-round-ability',$multiAction);$multi['questions'][0]=$multiSwap['question'];
$multiBlink=['roundId'=>$multi['roundId'],'actionId'=>str_repeat('2',32),'abilityId'=>'heldenblick','position'=>0,'answers'=>[['questionId'=>$multi['questions'][0]['id'],'selectedAnswers'=>[1]]]];
$multiRemoved=request('use-round-ability',$multiBlink);
$multiShield=array_replace($multiBlink,['actionId'=>str_repeat('3',32),'abilityId'=>'schutzschild']);request('use-round-ability',$multiShield);
request('use-round-ability',array_replace($multiShield,['actionId'=>str_repeat('4',32)]),409);
request('use-round-ability',array_replace($multiBlink,['actionId'=>str_repeat('5',32)]),409);
check(request('use-round-ability',$multiAction)==$multiSwap&&request('use-round-ability',$multiBlink)==$multiRemoved,'each ability has an independent once-per-round limit and stable replay after other abilities');
$multiAnswers=$roundAnswers($multi['questions']);$multiAnswers[0]['selectedAnswers']=[1,0];
$multiResult=request('save-result',['roundId'=>$multi['roundId'],'answers'=>$multiAnswers]);
$multiHistory=json_decode($pdo->query('SELECT action_json FROM quiz_hero_round_history WHERE result_id='.(int)$multiResult['resultId'])->fetchColumn(),true);
check(count($multiHistory)===3&&(int)$pdo->query('SELECT score FROM quiz_results WHERE id='.(int)$multiResult['resultId'])->fetchColumn()===14,'swap, elimination and shield combine on one question and persist all three actions with correct scoring');
// A frozen round from the previous local version keeps its one ability and action format.
$legacy=request('start-round',$roundPayload);$legacyAbility=array_column($legacy['abilities'],null,'id')['heldenblick'];
$pdo->prepare('UPDATE quiz_round_abilities SET snapshot_json=? WHERE round_id=?')->execute([json_encode(['heroKey'=>'hero','ability'=>$legacyAbility,'pool'=>[]]),$legacy['roundId']]);
$legacyAction=['roundId'=>$legacy['roundId'],'actionId'=>str_repeat('6',32),'position'=>0,'answers'=>[['questionId'=>$legacy['questions'][0]['id'],'selectedAnswers'=>[1]]]];
request('use-round-ability',$legacyAction);
$legacyStored=json_decode($pdo->query("SELECT action_json FROM quiz_round_abilities WHERE round_id='".$legacy['roundId']."'")->fetchColumn(),true);
$pdo->prepare('UPDATE quiz_round_abilities SET action_json=? WHERE round_id=?')->execute([json_encode($legacyStored[0]),$legacy['roundId']]);
request('use-round-ability',$legacyAction);
$legacyAnswers=$roundAnswers($legacy['questions']);$legacyAnswers[0]['selectedAnswers']=[1,0];request('save-result',['roundId'=>$legacy['roundId'],'answers'=>$legacyAnswers]);
check(true,'older local single-ability snapshots and actions remain replayable and scoreable');
$r=request('start-round',$roundPayload);
$action=['roundId'=>$r['roundId'],'actionId'=>str_repeat('c',32),'abilityId'=>'schutzschild','position'=>0,'answers'=>[['questionId'=>$r['questions'][0]['id'],'selectedAnswers'=>[1]]]];request('use-round-ability',$action);
$answers=$roundAnswers($r['questions']);$answers[0]['selectedAnswers']=[1,0];$saved=request('save-result',['roundId'=>$r['roundId'],'answers'=>$answers]);
check((int)$pdo->query('SELECT score FROM quiz_results WHERE id='.(int)$saved['resultId'])->fetchColumn()===14,'Schutzschild awards two points for the second try on the supported question only');
$r=request('start-round',$roundPayload);
$action=['roundId'=>$r['roundId'],'actionId'=>str_repeat('d',32),'abilityId'=>'neues-abenteuer','position'=>0,'answers'=>[['questionId'=>$r['questions'][0]['id'],'selectedAnswers'=>[]]]];$swapped=request('use-round-ability',$action);
check(!in_array($swapped['question']['id'],array_column($r['questions'],'id'),true)&&$swapped['question']['categoryId']===$abilityCat&&$swapped['question']['difficulty']==='medium','swap keeps category and prefers same difficulty without repeating any round question');
$r['questions'][0]=$swapped['question'];$saved=request('save-result',['roundId'=>$r['roundId'],'answers'=>$roundAnswers($r['questions'])]);
check((int)$pdo->query('SELECT COUNT(*) FROM quiz_question_results WHERE result_id='.(int)$saved['resultId'])->fetchColumn()===5,'swapped question does not create a second question result');
$r=request('start-round',['categoryId'=>$abilityCat,'questionIds'=>$abilityQuestionIds]);$action=['roundId'=>$r['roundId'],'actionId'=>str_repeat('e',32),'abilityId'=>'neues-abenteuer','position'=>0,'answers'=>[['questionId'=>$r['questions'][0]['id'],'selectedAnswers'=>[]]]];request('use-round-ability',$action,409);
check($pdo->query("SELECT action_json FROM quiz_round_abilities WHERE round_id='".$r['roundId']."'")->fetchColumn()===null,'no replacement leaves ability use unconsumed');
// Supported Hero replacements count as learning, but cannot unlock the first-try avatar reward.
$heroQs=[];
for($n=0;$n<2;$n++)$heroQs[]=request('admin-question-save',['categoryId'=>$abilityCat,'question'=>'Supported Hero '.$n.' '.$suffix,'answers'=>['A','B','C','D'],'correct'=>0,'difficulty'=>'hero','active'=>true,'worldIds'=>[]])['id'];
$r=request('start-round',['categoryId'=>$abilityCat,'questionIds'=>[$heroQs[0],...array_slice($abilityQuestionIds,0,4)]]);
$action=['roundId'=>$r['roundId'],'actionId'=>str_repeat('f',32),'abilityId'=>'neues-abenteuer','position'=>0,'answers'=>[['questionId'=>$heroQs[0],'selectedAnswers'=>[]]]];$replacement=request('use-round-ability',$action);$r['questions'][0]=$replacement['question'];
$saved=request('save-result',['roundId'=>$r['roundId'],'answers'=>$roundAnswers($r['questions'])]);
check($replacement['question']['id']===$heroQs[1]&&$saved['avatarRewards']===[],'a supported Hero replacement cannot unlock Astra through first-try performance');
check($pdo->query('SELECT assisted_ability FROM quiz_question_results WHERE result_id='.(int)$saved['resultId'].' AND question_id='.(int)$heroQs[1])->fetchColumn()==='neues-abenteuer','assisted status persists with immutable question results');
$history=$pdo->query('SELECT action_json FROM quiz_hero_round_history WHERE result_id='.(int)$saved['resultId'])->fetchColumn();check(json_decode($history,true)[0]['ability']['id']==='neues-abenteuer','ability action history survives independently of temporary round retention');
$short=request('start-round',['categoryId'=>$abilityCat,'questionIds'=>[$abilityQuestionIds[0]]]);check($short['abilities']===[],'short rounds do not permit abilities');
$newAbility=['title'=>'Global test '.$suffix,'description'=>'Global shield','effect'=>'shield','scope'=>'global','roundsRequired'=>1,'enabled'=>true];
request('admin-ability-save',$newAbility,422);
check(true,'admin cannot create ability definitions through the edit endpoint');
// A code-provided global definition, created only in the disposable test database.
$globalId='global-audit-'.$suffix;
$pdo->prepare('INSERT INTO quiz_abilities(id,title,description,effect,scope,rounds_required) VALUES(?,?,?,?,?,?)')->execute([$globalId,$newAbility['title'],$newAbility['description'],'shield','global',1]);
$r=request('start-round',$roundPayload);request('save-result',['roundId'=>$r['roundId'],'answers'=>$roundAnswers($r['questions'])]);
$items=array_column(request('account-abilities',[])['items'],null,'id');check($items[$globalId]['unlocked']&&$items[$globalId]['scope']==='global','global abilities unlock account-wide through qualifying rounds');
$otherAbilityHero=$pdo->query("SELECT avatar_key FROM quiz_avatars WHERE avatar_key<>'hero' AND enabled=1 AND deleted_at IS NULL ORDER BY avatar_key LIMIT 1")->fetchColumn();
$pdo->prepare("UPDATE quiz_users SET avatar_key=? WHERE id=?")->execute([$otherAbilityHero,$abilityUser]);
$items=array_column(request('account-abilities',[])['items'],null,'id');check(isset($items[$globalId])&&(!isset($items['heldenblick'])||!$items['heldenblick']['unlocked']),'hero switch preserves global access but hides other-hero abilities');
$before=(int)$pdo->query('SELECT COUNT(*) FROM quiz_user_abilities WHERE user_id='.$abilityUser)->fetchColumn();$pdo->prepare("UPDATE quiz_users SET avatar_key='hero' WHERE id=?")->execute([$abilityUser]);
check((int)$pdo->query('SELECT COUNT(*) FROM quiz_user_abilities WHERE user_id='.$abilityUser)->fetchColumn()===$before,'changing heroes never erases learned entitlements');
$a=array_column(request('admin-abilities')['abilities'],null,'id')[$globalId];
$edit=$newAbility+['id'=>$globalId,'contentVersion'=>$a['contentVersion']];$edit['enabled']=false;request('admin-ability-save',$edit);request('admin-ability-save',$edit,409);
check(!isset(array_column(request('account-abilities',[])['items'],null,'id')[$globalId]),'deactivated ability is hidden without deleting entitlements');
execute_sql_file(__DIR__.'/../database/migrations/022_hero_abilities.sql');
check(count(array_column(request('admin-abilities')['heroes'],null,'avatar_key')['hero']['abilityIds'])===3,'migration replay does not overwrite edited hero assignments');
